@RetryableTopic(attempts = "4", backoff = @Backoff(delay = 1000, multiplier = 2.0))
@KafkaListener(topics = "orders")
void consume(OrderEvent event) { service.apply(event); }   // throws -> retry topics -> -dlt

@DltHandler
void deadLetter(OrderEvent event) {
    audit.park(event);          // triage + alert; never a silent drop
}

